import json,numpy as np
m=json.load(open('/app/runs/012_reach/meta.json'));d=dict(zip(m['proprio']['layout'],m['proprio']['now']));q=np.array([d[f'right_eef_{k}'] for k in ('qx','qy','qz','qw')]);T=np.array(m['cameras']['robot_r1:right_realsense_link:Camera:0']['cam2world_gl']);fw=-T[:3,2];
def quat_to_R(q):
 x,y,z,w=q/np.linalg.norm(q);return np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]])
def R_to_q(R):
 # robust matrix to xyzw
 tr=np.trace(R)
 if tr>0:
  s=np.sqrt(tr+1.0)*2; w=.25*s; x=(R[2,1]-R[1,2])/s; y=(R[0,2]-R[2,0])/s; z=(R[1,0]-R[0,1])/s
 else:
  i=np.argmax(np.diag(R))
  if i==0:
   s=np.sqrt(1+R[0,0]-R[1,1]-R[2,2])*2; w=(R[2,1]-R[1,2])/s;x=.25*s;y=(R[0,1]+R[1,0])/s;z=(R[0,2]+R[2,0])/s
  elif i==1:
   s=np.sqrt(1+R[1,1]-R[0,0]-R[2,2])*2; w=(R[0,2]-R[2,0])/s;x=(R[0,1]+R[1,0])/s;y=.25*s;z=(R[1,2]+R[2,1])/s
  else:
   s=np.sqrt(1+R[2,2]-R[0,0]-R[1,1])*2; w=(R[1,0]-R[0,1])/s;x=(R[0,2]+R[2,0])/s;y=(R[1,2]+R[2,1])/s;z=.25*s
 return np.array([x,y,z,w])/np.linalg.norm([x,y,z,w])
R=quat_to_R(q); fl=R.T@fw
p=np.array([.4,4,1.15]); goal=np.array([.63,4.19,.95]); fd=(goal-p);fd/=np.linalg.norm(fd)
v=np.cross(fw,fd); c=np.dot(fw,fd); s=np.linalg.norm(v)
if s<1e-8: D=np.eye(3) if c>0 else np.diag([1,-1,-1])
else:
 K=np.array([[0,-v[2],v[1]],[v[2],0,-v[0]],[-v[1],v[0],0]])
 D=np.eye(3)+K+K@K*((1-c)/(s*s))
Rt=D@R;qt=R_to_q(Rt); print('q',q.tolist(),'forward',fw.tolist(),'local',fl.tolist(),'desired',fd.tolist(),'targetq',qt.tolist(),'targetForward',Rt@fl)
PY

