python - <<'PY'
import json,numpy as np
m=json.load(open('/app/runs/056_obs/meta.json'));T=np.array(m['cameras']['robot_r1:left_realsense_link:Camera:0']['cam2world_gl']);d=dict(zip(m['proprio']['layout'],m['proprio']['now']));print('T',T);print('left',[d[f'left_eef_{k}'] for k in ('x','y','z','qx','qy','qz','qw')])
for p in [(170,74),(198,205),(190,190)]:
 u,v=p;ray=np.array([(u-112)/181.3765,-(v-112)/181.3765,-1]);w=T[:3,:3]@ray;print(p,w)
 for z in [.1,.3,.6]:
  s=(z-T[2,3])/w[2]
  if s>0: print(z,np.round(T[:3,3]+s*w,3))
PY

